package analyzer
import("bufio";"encoding/json";"encoding/xml";"fmt";"io";"os";"path/filepath";"regexp";"sort";"strings";"sync";"time";"unicode/utf8";"github.com/jschimidt/xml2mysql/internal/config";"github.com/jschimidt/xml2mysql/internal/dump";"github.com/jschimidt/xml2mysql/internal/profile";"github.com/jschimidt/xml2mysql/internal/schema")
var intRE=regexp.MustCompile(`^[+-]?[0-9]+$`);var decRE=regexp.MustCompile(`^[+-]?[0-9]+\.[0-9]+$`);var dateRE=regexp.MustCompile(`^[0-9]{4}-[0-9]{2}-[0-9]{2}$`);var dtRE=regexp.MustCompile(`^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?$`)
func Run(c config.Config,v string)error{s:=time.Now();files,e:=filepath.Glob(filepath.Join(c.Input.Directory,c.Input.Pattern));if e!=nil{return e};sort.Strings(files);if len(files)==0{return fmt.Errorf("no XML files found")};p:=profile.Profile{Version:v,Job:c.Job.Name,StartedAt:s.UTC().Format(time.RFC3339),Target:profile.Target{Database:c.Target.Database,Version:c.Target.Version,Engine:c.Target.Engine,Charset:c.Target.Charset}};jobs:=make(chan string);out:=make(chan profile.TableProfile);errs:=make(chan error,c.Analysis.Workers);var wg sync.WaitGroup;for i:=0;i<c.Analysis.Workers;i++{wg.Add(1);go func(){defer wg.Done();for f:=range jobs{t,x:=scan(f,c.Analysis.SampleLimit,c.Analysis.DistinctLimit);if x!=nil{errs<-x;continue};out<-t}}()};go func(){for _,f:=range files{jobs<-f};close(jobs);wg.Wait();close(out);close(errs)}();for t:=range out{p.Tables=append(p.Tables,t);p.TotalBytes+=t.SizeBytes;p.TotalRows+=t.Rows};for x:=range errs{if x!=nil{return x}};sort.Slice(p.Tables,func(i,j int)bool{return p.Tables[i].Table<p.Tables[j].Table});f:=time.Now();p.FinishedAt=f.UTC().Format(time.RFC3339);p.DurationMS=f.Sub(s).Milliseconds();if p.DurationMS>0{p.ThroughputMB=(float64(p.TotalBytes)/1048576)/(float64(p.DurationMS)/1000)};for _,d:=range []string{"metadata","schema","reports","dump"}{if e=os.MkdirAll(filepath.Join(c.Output.Directory,d),0755);e!=nil{return e}};if e=writeJSON(filepath.Join(c.Output.Directory,"metadata","profile.json"),p);e!=nil{return e};m:=schema.BuildMapping(p);if e=writeJSON(filepath.Join(c.Output.Directory,"metadata","mapping.json"),m);e!=nil{return e};if e=os.WriteFile(filepath.Join(c.Output.Directory,"schema","schema.sql"),[]byte(schema.Render(m,c.Target.DatabaseName,c.Target.Engine,c.Target.Charset)),0644);e!=nil{return e};dumpPath,dumpRows,e:=dump.Write(c,m,v);if e!=nil{return e};if dumpRows!=p.TotalRows{return fmt.Errorf("dump row validation failed: analyzed=%d dumped=%d",p.TotalRows,dumpRows)};r:=fmt.Sprintf("xml2mysql %s\njob: %s\ndatabase: %s\nfiles: %d\nrows: %d\nbytes: %d\nduration: %s\nthroughput: %.2f MB/s\ndump: %s\ndump_rows: %d\nworkers: %d\n",v,c.Job.Name,c.Target.DatabaseName,len(p.Tables),p.TotalRows,p.TotalBytes,f.Sub(s),p.ThroughputMB,dumpPath,dumpRows,c.Analysis.Workers);return os.WriteFile(filepath.Join(c.Output.Directory,"reports","analysis.txt"),[]byte(r),0644)}
func scan(path string,sl,dl int)(profile.TableProfile,error){s:=time.Now();info,e:=os.Stat(path);if e!=nil{return profile.TableProfile{},e};f,e:=os.Open(path);if e!=nil{return profile.TableProfile{},e};defer f.Close();t:=profile.TableProfile{File:filepath.Base(path),Table:strings.TrimSuffix(filepath.Base(path),filepath.Ext(path)),SizeBytes:info.Size(),Columns:map[string]*profile.ColumnProfile{}};d:=xml.NewDecoder(bufio.NewReaderSize(f,1048576));in:=false;depth:=0;for{tok,x:=d.Token();if x==io.EOF{break};if x!=nil{return t,x};switch z:=tok.(type){case xml.StartElement:if z.Name.Local=="row"{in=true;depth=1;t.Rows++;continue};if in{depth++;if depth==2{var val string;if x=d.DecodeElement(&val,&z);x!=nil{return t,x};update(t.Columns,z.Name.Local,val,sl,dl);depth--}};case xml.EndElement:if in{depth--;if z.Name.Local=="row"&&depth==0{in=false}}}};for _,c:=range t.Columns{if c.MinChars==int(^uint(0)>>1){c.MinChars=0};if !c.DistinctTruncated{for v:=range c.Distinct{c.DistinctValues=append(c.DistinctValues,v)};sort.Strings(c.DistinctValues)};c.Distinct=nil};t.DurationMS=time.Since(s).Milliseconds();return t,nil}
func update(cols map[string]*profile.ColumnProfile,n,raw string,sl,dl int){c:=cols[n];if c==nil{c=&profile.ColumnProfile{MinChars:int(^uint(0)>>1),Distinct:map[string]bool{}};cols[n]=c};c.Present++;v:=strings.TrimSpace(raw);if v==""{c.Empty++};ch:=utf8.RuneCountInString(v);if ch<c.MinChars{c.MinChars=ch};if ch>c.MaxChars{c.MaxChars=ch};if len(v)>c.MaxBytes{c.MaxBytes=len(v)};if len(c.Samples)<sl&&v!=""{c.Samples=append(c.Samples,v)};if !c.DistinctTruncated{if !c.Distinct[v]&&len(c.Distinct)>=dl{c.DistinctTruncated=true;c.Distinct=nil}else if c.Distinct!=nil{c.Distinct[v]=true}};if intRE.MatchString(v){c.IntegerMatches++;u:=strings.TrimLeft(v,"+-");if len(u)>1&&u[0]=='0'{c.LeadingZero=true}};if decRE.MatchString(v){c.DecimalMatches++;q:=strings.TrimLeft(v,"+-");a:=strings.SplitN(q,".",2);p:=len(a[0])+len(a[1]);if p>c.MaxPrecision{c.MaxPrecision=p};if len(a[1])>c.MaxScale{c.MaxScale=len(a[1])}};if dateRE.MatchString(v){c.DateMatches++};if dtRE.MatchString(v){c.DateTimeMatches++;if i:=strings.IndexByte(v,'.');i>=0{n:=len(v)-i-1;if n>c.MaxFraction{c.MaxFraction=n}}}}
func writeJSON(path string,v any)error{b,e:=json.MarshalIndent(v,"","  ");if e!=nil{return e};return os.WriteFile(path,append(b,'\n'),0644)}
